// Embedded base64 audio data for 100% offline, failsafe playback on native Android/iOS and Web
// Bypasses resource resolution issues, Metro asset path hashing, and network requirement

export const SOUND_DATA_URIS = {
  click: 'data:audio/wav;base64,',
  lowTime: 'data:audio/wav;base64,',
  timeout: 'data:audio/wav;base64,',
} as const;

export type SoundKey = keyof typeof SOUND_DATA_URIS;
